
const WORDS=[{"id": 0, "w": "做主", "p": "zuòzhǔ", "t": "动词", "m": "làm chủ, quyết định", "coll": "自己做主、为别人做主", "s": "选择未来的道路时，我们应该认真思考，学会为自己做主。"}, {"id": 1, "w": "伤脑筋", "p": "shāng nǎojīn", "t": "动词短语", "m": "hao tổn tâm trí", "coll": "令人伤脑筋、为这件事伤脑筋", "s": "如何安排有限的时间，一直是一个让他伤脑筋的问题。"}, {"id": 2, "w": "枯燥", "p": "kūzào", "t": "形容词", "m": "nhàm chán, đơn điệu", "coll": "内容枯燥、枯燥乏味", "s": "如果学习内容过于枯燥，就容易让人失去兴趣。"}, {"id": 3, "w": "擅长", "p": "shàncháng", "t": "动词", "m": "thông thạo, giỏi về", "coll": "擅长沟通、擅长分析", "s": "她擅长分析问题，也善于把复杂的道理解释清楚。"}, {"id": 4, "w": "成本", "p": "chéngběn", "t": "名词", "m": "giá thành, chi phí", "coll": "降低成本、学习成本", "s": "选择培训课程时，除了考虑费用，也要考虑投入的时间成本。"}, {"id": 5, "w": "急躁", "p": "jízào", "t": "形容词", "m": "nôn nóng, nóng nảy, luống cuống", "coll": "性格急躁、不要急躁", "s": "面对暂时的困难，不要急躁，先冷静下来，再寻找解决办法。"}, {"id": 6, "w": "顾虑", "p": "gùlǜ", "t": "名词", "m": "nỗi lo âu, sự lo lắng", "coll": "消除顾虑、心有顾虑", "s": "老师耐心解答了大家的问题，帮助学生消除了顾虑。"}, {"id": 7, "w": "过度", "p": "guòdù", "t": "形容词", "m": "quá mức, quá", "coll": "过度担心、过度依赖", "s": "父母过度干预孩子的选择，可能会影响他们独立思考的能力。"}, {"id": 8, "w": "致使", "p": "zhìshǐ", "t": "动词／连词", "m": "làm cho, khiến cho; đến nỗi, cho nên", "coll": "致使计划推迟、致使交通受阻", "s": "连续多日的暴雨致使道路受损，原定的出行计划只好暂时推迟。"}, {"id": 9, "w": "终身", "p": "zhōngshēn", "t": "名词", "m": "cả đời, suốt đời", "coll": "终身学习、终身受益", "s": "保持终身学习的习惯，有助于我们不断适应新的工作要求。"}, {"id": 10, "w": "悔恨", "p": "huǐhèn", "t": "动词", "m": "hối hận, ân hận", "coll": "感到悔恨、悔恨不已", "s": "他对自己当年的草率决定十分悔恨，但也明白应该继续向前看。"}, {"id": 11, "w": "类似", "p": "lèisì", "t": "形容词", "m": "tương tự, giống", "coll": "类似的经历、与此类似", "s": "不少年轻人都有过类似的经历，因此很能理解他的感受。"}, {"id": 12, "w": "并非", "p": "bìngfēi", "t": "副词", "m": "không phải", "coll": "并非如此、并非偶然", "s": "一次失败并非意味着你不适合这条道路。"}, {"id": 13, "w": "精确", "p": "jīngquè", "t": "形容词", "m": "chính xác", "coll": "精确计算、精确的数据", "s": "作出判断之前，我们需要掌握更加精确的数据。"}, {"id": 14, "w": "天生", "p": "tiānshēng", "t": "形容词", "m": "trời sinh, bẩm sinh", "coll": "天生的优势、天生擅长", "s": "没有人天生就擅长所有事情，许多能力都需要后天培养。"}, {"id": 15, "w": "挫折", "p": "cuòzhé", "t": "名词", "m": "trở ngại, vấp váp, thất bại", "coll": "面对挫折、经受挫折", "s": "面对挫折时，与其一味责怪自己，不如认真总结经验。"}, {"id": 16, "w": "意志", "p": "yìzhì", "t": "名词", "m": "ý chí", "coll": "坚定意志、磨炼意志", "s": "长期坚持一项任务，不仅需要兴趣，也需要坚定的意志。"}, {"id": 17, "w": "敏锐", "p": "mǐnruì", "t": "形容词", "m": "nhạy bén, nhanh nhạy", "coll": "观察敏锐、敏锐的判断力", "s": "她凭借敏锐的观察力，很快发现了问题的关键。"}, {"id": 18, "w": "畏惧", "p": "wèijù", "t": "动词", "m": "sợ, khiếp sợ", "coll": "畏惧困难、毫不畏惧", "s": "真正的勇气并不是毫不畏惧，而是害怕时仍愿意尝试。"}, {"id": 19, "w": "勇于", "p": "yǒngyú", "t": "动词", "m": "can đảm, dũng cảm, mạnh dạn", "coll": "勇于尝试、勇于承担责任", "s": "年轻人既要勇于尝试，也要学会为自己的选择承担责任。"}, {"id": 20, "w": "伴随", "p": "bànsuí", "t": "动词", "m": "đi đôi với, đi kèm", "coll": "伴随成长、伴随着变化", "s": "每一次成长往往都伴随着新的挑战和责任。"}, {"id": 21, "w": "日益", "p": "rìyì", "t": "副词", "m": "ngày càng", "coll": "日益增长、日益重要", "s": "随着社会的发展，持续学习的能力变得日益重要。"}, {"id": 22, "w": "昔日", "p": "xīrì", "t": "名词", "m": "ngày xưa, thời trước", "coll": "昔日的同学、回想昔日", "s": "回想昔日的校园生活，他仍然记得老师给予自己的鼓励。"}, {"id": 23, "w": "风光", "p": "fēngguang", "t": "形容词", "m": "vẻ vang, huy hoàng", "coll": "昔日风光、风光一时", "s": "不要只看到别人成功时的风光，也要了解他们背后付出的努力。"}, {"id": 24, "w": "亏损", "p": "kuīsǔn", "t": "动词", "m": "hao hụt, lỗ vốn", "coll": "出现亏损、长期亏损", "s": "由于经营方式未能及时调整，这家企业连续两年出现亏损。"}, {"id": 25, "w": "倒闭", "p": "dǎobì", "t": "动词", "m": "phá sản, sập tiệm", "coll": "企业倒闭、面临倒闭", "s": "那家店因为经营不善最终倒闭了，员工们开始寻找新的工作。"}, {"id": 26, "w": "金融", "p": "jīnróng", "t": "名词", "m": "tài chính", "coll": "金融行业、金融知识", "s": "进入金融行业之前，她系统学习了相关的专业知识。"}, {"id": 27, "w": "危机", "p": "wēijī", "t": "名词", "m": "khủng hoảng", "coll": "面临危机、应对危机", "s": "面对危机，企业更需要冷静分析和及时调整。"}, {"id": 28, "w": "盈利", "p": "yínglì", "t": "动词", "m": "thu lợi", "coll": "实现盈利、盈利能力", "s": "经过一年的调整，这家小公司终于实现了盈利。"}, {"id": 29, "w": "运行", "p": "yùnxíng", "t": "动词", "m": "vận hành", "coll": "正常运行、系统运行", "s": "设备投入使用后，工作人员每天都要检查它是否正常运行。"}, {"id": 30, "w": "裁员", "p": "cáiyuán", "t": "动词", "m": "cắt giảm nhân sự", "coll": "公司裁员、裁员计划", "s": "公司宣布裁员计划后，不少员工开始重新考虑职业方向。"}, {"id": 31, "w": "意味着", "p": "yìwèizhe", "t": "动词", "m": "có nghĩa là, ngụ ý", "coll": "意味着变化、意味着责任", "s": "获得更多自由，也意味着需要承担更多责任。"}, {"id": 32, "w": "英明", "p": "yīngmíng", "t": "形容词", "m": "sáng suốt, minh mẫn", "coll": "英明的决定、十分英明", "s": "事实证明，提前培养年轻骨干是一个英明的决定。"}, {"id": 33, "w": "称心如意", "p": "chènxīn rúyì", "t": "成语", "m": "như ý muốn, hợp ý", "coll": "称心如意的工作、事事称心如意", "s": "没有一份工作能让人事事称心如意，关键是找到适合自己的方向。"}, {"id": 34, "w": "除", "p": "chú", "t": "介词", "m": "ngoài... ra, trừ... ra", "coll": "除学习之外、除他以外", "s": "除专业知识之外，良好的沟通能力也是求职时的重要优势。"}, {"id": 35, "w": "争先恐后", "p": "zhēngxiān kǒnghòu", "t": "成语", "m": "tranh lên trước sợ rớt lại phía sau", "coll": "争先恐后地报名、争先恐后地发言", "s": "得知有交流机会，同学们争先恐后地报名，希望开阔自己的眼界。"}, {"id": 36, "w": "热门", "p": "rèmén", "t": "形容词／名词", "m": "sự phổ biến, sự được nhiều người ưa chuộng", "coll": "热门专业、热门话题", "s": "选择热门专业之前，应该先了解它是否真正适合自己。"}, {"id": 37, "w": "以致", "p": "yǐzhì", "t": "连词", "m": "cho nên, vì vậy", "coll": "以致耽误进度、以致忘了休息", "s": "他过于在意别人的评价，以致迟迟不敢作出决定。"}, {"id": 38, "w": "饱和", "p": "bǎohé", "t": "动词", "m": "bão hòa", "coll": "市场饱和、接近饱和", "s": "这个地区同类培训机构过多，市场已经接近饱和。"}, {"id": 39, "w": "就业", "p": "jiùyè", "t": "动词", "m": "tìm việc làm, có việc làm", "coll": "就业机会、实现就业", "s": "学校通过加强实践教学，帮助毕业生提升就业能力。"}, {"id": 40, "w": "及早", "p": "jízǎo", "t": "副词", "m": "nhanh chóng, sớm", "coll": "及早准备、及早发现", "s": "明确目标以后，就应该及早准备，不要等到最后才匆忙行动。"}, {"id": 41, "w": "机遇", "p": "jìyù", "t": "名词", "m": "cơ hội, thời cơ", "coll": "把握机遇、发展机遇", "s": "机遇出现时，只有做好准备的人，才更有可能把握住它。"}, {"id": 42, "w": "心灵", "p": "xīnlíng", "t": "名词", "m": "tâm hồn", "coll": "心灵成长、走进心灵", "s": "阅读和交流能帮助我们理解他人的心灵，也更清楚地认识自己。"}, {"id": 43, "w": "免疫", "p": "miǎnyì", "t": "动词", "m": "miễn dịch", "coll": "产生免疫、对挫折免疫", "s": "这种训练并不能让人对所有挫折免疫，但能帮助我们更快恢复。"}, {"id": 44, "w": "决策", "p": "juécè", "t": "名词／动词", "m": "ra quyết định chiến lược", "coll": "作出决策、参与决策", "s": "作出重要决策之前，应当充分了解情况，权衡可能的结果。"}];
